#include <bits/stdc++.h>
using namespace std;

const int MOD = 998244353;

long long modpow(long long a, long long e = MOD - 2) {
    long long r = 1;
    while (e) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    int maxN = 50000;
    vector<long long> fact(maxN + 1), invfact(maxN + 1);
    fact[0] = 1;
    for (int i = 1; i <= maxN; ++i) fact[i] = fact[i - 1] * i % MOD;
    invfact[maxN] = modpow(fact[maxN]);
    for (int i = maxN; i > 0; --i) invfact[i - 1] = invfact[i] * i % MOD;
    auto C = [&](int n, int k) -> long long {
        if (k < 0 || k > n) return 0;
        return fact[n] * invfact[k] % MOD * invfact[n - k] % MOD;
    };
    long long ans = 0;
    for (int k = 1; k <= n; ++k) {
        int s = n - k;
        if (s < 0) continue;
        // c from 0 to floor(s/2)
        int maxc = s / 2;
        for (int c = 0; c <= maxc; ++c) {
            int t = s - 2 * c; // number of d pairs
            if (t < 0) continue;
            // n must equal 2c + 3t => 2c + 3t = n
            if (2 * c + 3 * t != n) continue;
            // beauty = 2^t
            long long ways = C(n, c);          // choose which colors are c
            ways = ways * C(n - c, t) % MOD;   // choose which of remaining are d (t colors)
            // remaining colors = n - c - t = c + 2t? Wait n - c - t = n - c - t. But n = 2c+3t => n-c-t = c+2t. Those are b colors.
            // assign each b color to A or B: 2^(n - c - t)
            ways = ways * modpow(2, n - c - t) % MOD;
            long long beauty = modpow(2, t);
            ans = (ans + ways * beauty) % MOD;
        }
    }
    cout << ans % MOD << "\n";
    return 0;
}
